{"command":"echo "=== MAC vendors ==="; for mac in dc:f8:b9:ef:ba:f 18:e7:b0:e8:22:c0 78:94:b4:a8:90:1a d6:48:d4:8a:fd:4b; do v=$(curl -s --max-time 8 "https://api.macvendors.com/$mac"); echo "$mac => $v"; sleep 1.2; done; echo; echo "=== HTTP banners ==="; for ip in 192.168.1.1 192.168.1.10 192.168.1.16 192.168.1.254 192.168.1.66; do echo "--- $ip ---"; curl -s -m 4 -A "Mozilla/5.0" "http://$ip/" | python3 -c "import sys,re; h=sys.stdin.read(); t=re.findall(r'<title[^>]*>(.*?)</title>', h, re.S|re.I); m=re.findall(r'(Server|WWW-Authenticate):.*', h[:0]); print('title:', (t[0].strip()[:100] if t else h[:150].replace(chr(10),' ')))" 2>/dev/null; curl -sI -m 4 "http://$ip/" | head -5; done; echo; echo "=== FTP greeting 192.168.1.66 ==="; (printf ''; sleep 3) | nc 192.168.1.66 21 | head -2; echo; echo "=== SSDP probe ==="; python3 - <<'EOF'
import socket
s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM, socket.IPTOS_MULTICAST)
s.settimeout(4)
msg = b"M-SEARCH * HTTP/1.1\r\nHOST:239.255.255.250:1900\r\nST:ssdp:all\r\nMAN:\"ssdp:discover\"\r\nMX:2\r\n\r\n"
try:
    s.sendto(msg, ("239.255.255.250", 1900))
    for _ in range(10):
        data, addr = s.recvfrom(4096)
        print(addr[0], "::", data[:220].decode("utf-8", "replace").replace("\r\n", " | "))
except socket.timeout:
    print("(no SSDP responses)")
EOF","description":"Identify LAN devices by MAC vendor, HTTP banners, FTP greeting, and SSDP","timeout":120000}
